import { FEATURES } from './features.mjs';
export const traditionHTML = `<div class="heritage-heading"><p class="eyebrow">A TRIBUTE TO OUR COAST</p><h2 id="dialog-title">Tulunadu <span lang="kn">ತುಳುನಾಡು</span></h2><p class="heritage-deck">For the hands that taught us.</p></div><figure class="heritage-scene"><img src="/assets/tulunadu-family.webp" width="1672" height="941" alt="Imagined family sharing Chenne Mane on a coastal verandah as rain falls outside"><figcaption>An imagined family afternoon in Tulunadu</figcaption></figure><div class="heritage-prose"><p class="heritage-lead">A wooden board. A handful of shells. Someone across from you, ready for one more game.</p><p>In Tulunadu, Chenne Mane carries memories of family, rainy Aati afternoons, and lessons learned by sitting down together. The worn hollows of a board hold patience, laughter, and the small satisfaction of a clever move.</p><p>From Mangaluru and Udupi to the neighbouring coast of Kundapura, languages and customs have their own voices. This tribute makes room for that variety, and for every family’s way of playing.</p><p>Ask an elder how they played. Teach a friend. Keep a place across the board.</p>${FEATURES.music ? `<div class="heritage-listening"><p class="eyebrow">SOUNDS OF THE COAST</p><h3>Let a performance keep you company.</h3><div id="heritage-track-list" class="heritage-tracks"></div><p id="heritage-music-status" role="status" class="text-small">Pause and volume controls are below the board.</p><button class="text-button" id="heritage-music-pause">Pause music</button></div>` : ''}<button class="primary-button" data-guide="tutorial">Learn a round together</button></div>`;
